from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    # The requested slow-SMA length was not specified; this uses 20 five-minute bars.
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            fill_forward=False,
            extended_market_hours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute, fill_forward=False)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol,
            self.five_minute_consolidator
        )

        self.pending_crossover_end = None
        self.held_contract = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if old_fast is not None and old_slow is not None:
            if old_fast <= old_slow and self.fast.Current.Value > self.slow.Current.Value:
                self.pending_crossover_end = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationSafety()
        self.HandleOptionExit(data)
        self.HandlePendingEntry(data)

    def HandlePendingEntry(self, data):
        if self.pending_crossover_end is None:
            return

        if self.Time > self.pending_crossover_end:
            self.pending_crossover_end = None
            return

        if self.Time != self.pending_crossover_end:
            return

        self.pending_crossover_end = None

        if self.blocked_entry_date == self.Time.date():
            return

        if not self.IsEntryTime():
            return

        if self.HasOptionPosition() or self.entry_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped - no SPY option chain in Slice.")
            return

        spot = self.Securities[self.spy_symbol].Price
        if spot <= 0:
            self.Debug(f"{self.Time}: Entry skipped - invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped - no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped - no call at {selected_expiry} "
                f"with strike >= {minimum_strike:.2f}."
            )
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Submitted entry for 1 {selected.Symbol}; "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def HandleOptionExit(self, data):
        if not self.HasOptionPosition():
            return

        expiry_date = self.held_contract.ID.Date.date()

        if self.Time.date() == self.PreviousTradingDay(expiry_date) and self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitExit("expiration-eve time stop")
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_fill_price is not None and midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit(f"50% profit target at midpoint {midpoint:.2f}")

    def HandleExpirationSafety(self):
        if not self.HasOptionPosition():
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration safety liquidation")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        if self.equity_liquidation_order_id is None:
            ticket = self.MarketOrder(self.spy_symbol, -quantity)
            self.equity_liquidation_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position of {quantity}; "
                f"submitted immediate liquidation."
            )

    def SubmitExit(self, reason):
        if not self.HasOptionPosition() or self.exit_order_id is not None:
            return

        self.CancelOpenExitOrders()

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Submitted option exit ({reason}).")

    def CancelOpenExitOrders(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None:
            ticket.Cancel()

        self.exit_order_id = None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_contract} "
                    f"at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"{self.Time}: Entry order did not fill: {order_event.Status}.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_liquidation_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_liquidation_order_id = None

    def HasOptionPosition(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def IsEntryTime(self):
        current_time = self.Time.time()
        return current_time >= timedelta(hours=9, minutes=45) and current_time <= timedelta(hours=14, minutes=30)

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        while not self.spy.Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate
