from datetime import datetime, timedelta, time

from QuantConnect import DataNormalizationMode, OrderStatus, Resolution
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Data.Market import OptionRight
from QuantConnect.Indicators import RollingWindow


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    FAST_PERIOD = 5
    # The requested slow-SMA period was not specified; adjust this parameter if needed.
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=730))

        self.closes = RollingWindow[float](self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry = False

        self.held_contract = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # The minute consolidator is aligned to the algorithm's New York time zone.
        # With regular-hours SPY data, the first session bar ends at 09:35.
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(self.closes[i] for i in range(self.FAST_PERIOD)) / self.FAST_PERIOD
        current_slow = sum(self.closes[i] for i in range(self.SLOW_PERIOD)) / self.SLOW_PERIOD

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_end = bar.EndTime.time()
        if bullish_cross and time(9, 45) <= bar_end <= time(14, 30):
            self.pending_entry = True

    def OnData(self, slice):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationRisk()

        if self.held_contract is not None:
            self.EvaluateExit(slice)

        if self.pending_entry:
            self.pending_entry = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.entry_fill_price is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        eligible_expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= today + timedelta(days=7)
            }
        )

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        expiration = eligible_expirations[0]
        spy_price = float(self.Securities[self.spy].Price)

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and float(contract.Strike) >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no qualifying call for {expiration} at SPY {spy_price:.2f}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: buying 1 {selected.Symbol}.")

    def EvaluateExit(self, slice):
        if self.held_contract is None:
            return

        today = self.Time.date()
        expiration = self.held_contract.ID.Date.date()

        if (
            self.Time.time() >= time(15, 45)
            and today < expiration
            and self.IsTradingDayImmediatelyBeforeExpiration(today, expiration)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None:
            return

        bid = float(quote.Bid.Close) if quote.Bid is not None else 0.0
        ask = float(quote.Ask.Close) if quote.Ask is not None else 0.0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit(
                f"50% profit target reached (midpoint {midpoint:.2f}, "
                f"entry {self.entry_fill_price:.2f})"
            )

    def HandleExpirationRisk(self):
        if self.held_contract is None:
            return

        today = self.Time.date()
        expiration = self.held_contract.ID.Date.date()

        if today >= expiration:
            self.no_entry_date = today
            self.SubmitExit("expiration processing safeguard")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_contract, -quantity)
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted: {reason}; {self.held_contract}.")

    def IsTradingDayImmediatelyBeforeExpiration(self, today, expiration):
        if not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(today, time.min)
        ):
            return False

        next_day = today + timedelta(days=1)
        while next_day < expiration:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime.combine(next_day, time.min)
            ):
                return False
            next_day += timedelta(days=1)

        return next_day == expiration

    def HandleUnexpectedSpyHolding(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if not self.Transactions.GetOpenOrders(self.spy):
            self.Debug("Unexpected SPY position from exercise/assignment; liquidating.")
            self.Liquidate(self.spy)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at "
                    f"{self.entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug("Entry order canceled or invalid.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}.")
                self.held_contract = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

        if order_event.Symbol == self.spy and self.Portfolio[self.spy].Quantity != 0:
            self.Debug("SPY exercise/assignment position detected; liquidating immediately.")
            self.Liquidate(self.spy)
